import { register } from '../service_injector'
import {
    diagramEditSessionService,
    type DiagramEditSessionService,
} from './diagram_edit_session_service'
import type {
    ReadonlyDiagramData,
} from './diagram_edit_types'
import { parseDiagramData, serializeDiagramData, type DiagramData } from './diagram_data'
import {
    diagramViewService,
    type DiagramViewService,
    type SaveEditedDiagramCopyRequest,
} from './diagram_view_service'

const SAVE_STATUS_CHANGED_EVENT = 'diagramSaveStatusChanged'

export type DiagramSaveStatus = 'idle' | 'saving'

type DiagramSaveSession = Pick<DiagramEditSessionService,
    | 'acknowledgeSavedCopy'
    | 'getDirtySnapshot'
    | 'getEditableDiagram'
    | 'getOriginalDiagramSnapshot'
    | 'getSavedRecordSnapshot'
    | 'getSessionSnapshot'
>

type DiagramCopyPersistence = Pick<DiagramViewService, 'saveEditedDiagramCopy'>
type DiagramSerializer = (diagram: ReadonlyDiagramData) => string

function canonicalDiagramContent(diagram: ReadonlyDiagramData) {
    return serializeDiagramData(diagram as DiagramData)
}

/** Owns explicit edited-diagram save progress and coordinates session acknowledgement. */
export class DiagramSaveService extends EventTarget {
    private readonly persistence: DiagramCopyPersistence
    private readonly serialize: DiagramSerializer
    private readonly session: DiagramSaveSession
    private status: DiagramSaveStatus = 'idle'

    constructor(
        session: DiagramSaveSession = diagramEditSessionService,
        persistence: DiagramCopyPersistence = diagramViewService,
        serialize: DiagramSerializer = canonicalDiagramContent,
    ) {
        super()
        this.persistence = persistence
        this.serialize = serialize
        this.session = session
    }

    getStatusSnapshot = () => this.status

    subscribeStatus = (listener: () => void) => {
        this.addEventListener(SAVE_STATUS_CHANGED_EVENT, listener)

        return () => this.removeEventListener(SAVE_STATUS_CHANGED_EVENT, listener)
    }

    async save() {
        if (this.status === 'saving') throw new Error('Diagram save is already in progress')
        if (!this.session.getDirtySnapshot()) throw new Error('Cannot save a diagram without changes')
        const editableDiagram = this.session.getEditableDiagram()
        const originalDiagram = this.session.getOriginalDiagramSnapshot()
        const editSession = this.session.getSessionSnapshot()
        if (!editableDiagram || !originalDiagram || !editSession) throw new Error('Cannot save without an active diagram edit session')

        const content = this.serialize(editableDiagram)
        const savedDiagram = parseDiagramData(content)
        const request: SaveEditedDiagramCopyRequest = {
            content,
            savedRecord: this.session.getSavedRecordSnapshot(),
            sourceRecord: originalDiagram.record,
        }
        this.setStatus('saving')
        try {
            const record = await this.persistence.saveEditedDiagramCopy(request)
            const currentSession = this.session.getSessionSnapshot()
            if (currentSession?.sourceDiagramId === editSession.sourceDiagramId) {
                const currentDiagram = this.session.getEditableDiagram()
                const savedDataIsCurrent = !!currentDiagram && this.serialize(currentDiagram) === content
                this.session.acknowledgeSavedCopy(record, savedDiagram, savedDataIsCurrent)
            }

            return record
        } finally {
            this.setStatus('idle')
        }
    }

    private setStatus(status: DiagramSaveStatus) {
        if (status === this.status) return

        this.status = status
        this.dispatchEvent(new Event(SAVE_STATUS_CHANGED_EVENT))
    }
}

export const diagramSaveService = register('diagramSaveService', new DiagramSaveService())

const { validateAgentTokenUsage } = require('../../../../shared/agent_usage_math.mjs');
const {
    ClaudeFileResultDecoder,
    accumulatedClaudeUsage,
    claudeAssistantText,
    claudeTranscriptEvents,
    claudeUsage,
    recordClaudeAssistantUsage,
} = require('./agent_claude_events');
const { codexTranscriptEvents } = require('./agent_codex_events');
const { normalizeCodexEvent } = require('./agent_codex_event');
const { JsonLineBuffer } = require('./agent_event_utils');

const MISSING_SESSION_CODES = new Set([
    'conversation_not_found',
    'invalid_session_id',
    'resume_session_not_found',
    'session_not_found',
    'thread_not_found',
]);

// Codex exec reports one `turn.completed` per turn whose counters already cover every model request
// in that turn, so this needs no accumulation of its own (the streaming app-server protocol does;
// see `codexTurnCounters`). Cached tokens are a subset of input_tokens and reasoning a subset of
// output_tokens; subtracting here makes the buckets disjoint and inputTokens fresh-only, matching
// how claude reports them.
function codexUsage(event) {
    const usage = event.usage;
    if (event.type !== 'turn.completed' || !usage || typeof usage !== 'object' || Array.isArray(usage)) return null;
    const cachedInputTokens = usage.cached_input_tokens;

    const inputTokens = usage.input_tokens;
    const outputTokens = usage.output_tokens;
    const reasoningTokens = usage.reasoning_output_tokens ?? 0;

    return validateAgentTokenUsage({
        cachedInputTokens: cachedInputTokens ?? 0,
        inputTokens: inputTokens - (cachedInputTokens ?? 0),
        outputTokens: outputTokens - reasoningTokens,
        reasoningTokens,
    }, usage.total_tokens);
}

function providerTranscriptEvents(agent, event) {
    if (agent !== 'codex') return claudeTranscriptEvents(event);
    if (event.type !== 'item.completed' || !event.item) return [];

    return codexTranscriptEvents(event.item);
}

function eventCodes(event) {
    return [event.code, event.error?.code, event.error?.type, event.result?.code, event.subtype]
        .filter((value) => typeof value === 'string')
        .map((value) => value.toLowerCase());
}

function codexAssistantText(event) {
    if (event.type !== 'item.completed' || event.item?.type !== 'agent_message') return '';

    return typeof event.item.text === 'string' ? event.item.text : '';
}

function nestedErrorMessage(value) {
    if (typeof value === 'string') {
        try {
            return nestedErrorMessage(JSON.parse(value));
        } catch {
            return value;
        }
    }
    if (!value || typeof value !== 'object' || Array.isArray(value)) return '';

    return nestedErrorMessage(value.message ?? value.error ?? value.result);
}

function providerErrorText(agent, event) {
    if (event.type === 'error') return nestedErrorMessage(event.message ?? event.error);
    if (agent === 'codex' && event.type === 'turn.failed') return nestedErrorMessage(event.error);
    if (agent === 'codex' && event.type === 'item.completed' && event.item?.type === 'error') {
        return nestedErrorMessage(event.item.message ?? event.item.error);
    }
    if (agent === 'claude' && event.type === 'result' && event.is_error === true) {
        return nestedErrorMessage(event.error ?? event.result ?? event.message);
    }

    return '';
}

function providerConversationId(agent, event) {
    if (agent === 'codex' && event.type === 'thread.started') return event.thread_id ?? event.thread?.thread_id ?? null;
    if (agent === 'claude' && typeof event.session_id === 'string') return event.session_id;

    return null;
}

function isTurnEvent(agent, event) {
    if (agent === 'codex') return event.type === 'turn.started' || event.type === 'item.started' || event.type === 'item.completed';
    if (agent === 'claude') return event.type === 'assistant' || event.type === 'user';

    return false;
}

function isMissingSession(agent, event, turnStarted) {
    if (turnStarted) return false;
    if (agent !== 'codex' && agent !== 'claude') return false;
    const isFailureEvent = event.type === 'error' || (agent === 'claude' && event.type === 'result' && event.is_error === true);

    return isFailureEvent && eventCodes(event).some((code) => MISSING_SESSION_CODES.has(code));
}

class AgentProviderProtocolParser {
    constructor(agent, onEvent, onMalformed, rootPath) {
        this.agent = agent;
        this.lines = new JsonLineBuffer(agent, (line) => this.parseLine(line));
        this.onEvent = onEvent;
        this.onMalformed = onMalformed;
        this.rootPath = rootPath;
        this.turnStarted = false;
        this.claudeFileResultDecoder = agent === 'claude' ? new ClaudeFileResultDecoder(rootPath) : null;
        this.claudeMessageUsages = new Map();
    }

    push(chunk) {
        this.lines.push(chunk);
    }

    finish() {
        this.lines.finish();
    }

    providerUsage(event) {
        if (this.agent === 'codex') return codexUsage(event);
        const isSubAgentResult = typeof event.parent_tool_use_id === 'string' && event.parent_tool_use_id.length > 0;
        if (event.type !== 'result' || isSubAgentResult) return null;
        const usage = claudeUsage(event, accumulatedClaudeUsage(this.claudeMessageUsages));
        this.claudeMessageUsages.clear();

        return usage;
    }

    parseLine(line) {
        let event;
        try {
            event = JSON.parse(line);
        } catch {
            this.onMalformed(line);
            return;
        }
        if (!event || typeof event !== 'object' || Array.isArray(event)) {
            this.onMalformed(line);
            return;
        }

        const missingSession = isMissingSession(this.agent, event, this.turnStarted);
        this.turnStarted = this.turnStarted || isTurnEvent(this.agent, event);
        if (this.agent === 'claude') recordClaudeAssistantUsage(this.claudeMessageUsages, event);
        const usage = this.providerUsage(event);
        const assistantText = this.agent === 'codex' ? codexAssistantText(event) : claudeAssistantText(event);
        this.onEvent({
            assistantText,
            conversationId: providerConversationId(this.agent, event),
            errorText: providerErrorText(this.agent, event),
            missingSession,
            providerEvents: this.agent === 'codex' && event.type === 'item.completed'
                ? [normalizeCodexEvent(event.item, 'completed', this.rootPath)].filter((providerEvent) => providerEvent !== null)
                : this.claudeFileResultDecoder?.decode(event) ?? [],
            transcriptEvents: providerTranscriptEvents(this.agent, event),
            turnStarted: this.turnStarted,
            usage,
        });
    }
}

function createAgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath) {
    if (agent !== 'codex' && agent !== 'claude') return null;

    return new AgentProviderProtocolParser(agent, onEvent, onMalformed, rootPath);
}

module.exports = { createAgentProviderProtocolParser, isMissingSession };

const { normalizedContent } = require('./agent_event_utils');
const { countFileContentLines, countPatchLines } = require('./agent_file_change');
const { codexChangedPaths } = require('./agent_codex_events');
const { boundedAgentResult } = require('../../../../shared/agent_conversations.mjs');

const MAX_EVENT_CONTENT_LENGTH = 16_384;
const MAX_EVENT_FIELDS = 12;
const TRUNCATED_EVENT_SUFFIX = '\n[event content truncated]';
const UNIFIED_DIFF_HUNK_PATTERN = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/u;
const SUPPORTED_CODEX_ITEM_TYPES = new Set([
    'collabAgentToolCall',
    'commandExecution',
    'contextCompaction',
    'dynamicToolCall',
    'enteredReviewMode',
    'exitedReviewMode',
    'fileChange',
    'imageView',
    'mcpToolCall',
    'plan',
    'reasoning',
    'webSearch',
]);

function itemStatus(item, lifecycleStatus) {
    return typeof item.status === 'string' ? item.status : lifecycleStatus;
}

function optionalContent(value) {
    const content = normalizedContent(value) ?? '';
    if (content.length <= MAX_EVENT_CONTENT_LENGTH) return content;

    const retainedLength = MAX_EVENT_CONTENT_LENGTH - TRUNCATED_EVENT_SUFFIX.length;

    return `${content.slice(0, retainedLength)}${TRUNCATED_EVENT_SUFFIX}`;
}

function readableFieldName(fieldName) {
    return fieldName
        .replace(/([a-z])([A-Z])/gu, '$1 $2')
        .replace(/[_-]+/gu, ' ')
        .replace(/^./u, (character) => character.toUpperCase());
}

function parseStructuredString(value) {
    const trimmed = value.trim();
    if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return value;

    try {
        return JSON.parse(trimmed);
    } catch {
        return 'Structured event detail unavailable';
    }
}

function selectedFieldValue(value) {
    if (typeof value === 'string') return value;
    if (typeof value === 'number' || typeof value === 'boolean') return String(value);
    if (!Array.isArray(value)) return null;
    const values = value
        .filter((entry) => typeof entry === 'string' || typeof entry === 'number' || typeof entry === 'boolean')
        .map(String);

    return values.length > 0 ? values.join(', ') : null;
}

function selectedEventContent(value, boundContent = true) {
    if (value === undefined || value === null) return '';
    const structuredValue = typeof value === 'string' ? parseStructuredString(value) : value;
    if (typeof structuredValue === 'string') return boundContent ? optionalContent(structuredValue) : structuredValue;
    if (typeof structuredValue === 'number' || typeof structuredValue === 'boolean') return String(structuredValue);
    if (Array.isArray(structuredValue)) {
        const lines = structuredValue
            .map((entry) => (
                entry && typeof entry === 'object'
                    ? selectedEventContent(entry, boundContent)
                    : selectedFieldValue(entry)
            ))
            .filter((entry) => entry !== null && entry.length > 0)
            .slice(0, MAX_EVENT_FIELDS);

        const content = lines.join('\n');

        return boundContent ? optionalContent(content) : content;
    }
    if (typeof structuredValue !== 'object') return '';
    const lines = Object.entries(structuredValue)
        .map(([fieldName, fieldValue]) => {
            const selectedValue = selectedFieldValue(fieldValue);

            return selectedValue === null ? null : `${readableFieldName(fieldName)}: ${selectedValue}`;
        })
        .filter((entry) => entry !== null)
        .slice(0, MAX_EVENT_FIELDS);

    const content = lines.join('\n');

    return boundContent ? optionalContent(content) : content;
}

function fileChangeContent(changes) {
    if (!Array.isArray(changes)) return '';

    return changes
        .filter((change) => typeof change?.path === 'string' && typeof change?.kind?.type === 'string')
        .map(({ kind, path }) => `${kind.type}: ${path}`)
        .join('\n');
}

