function normalizeCodexEvent(item, lifecycleStatus, rootPath) {
    if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') return null;
    const type = canonicalCodexItemType(item.type);
    if (!SUPPORTED_CODEX_ITEM_TYPES.has(type)) return null;
    const normalizedItem = type === item.type ? item : { ...item, type };
    if (type === 'reasoning') return reasoningEvent(normalizedItem, lifecycleStatus);
    if (type === 'commandExecution') return commandEvent(normalizedItem, lifecycleStatus);
    if (type === 'fileChange') return fileEvent(normalizedItem, lifecycleStatus, rootPath);
    if (type === 'mcpToolCall') return mcpEvent(normalizedItem, lifecycleStatus);
    if (type === 'dynamicToolCall') return dynamicToolEvent(normalizedItem, lifecycleStatus);
    if (type === 'collabAgentToolCall') return collaborationEvent(normalizedItem, lifecycleStatus);
    if (type === 'webSearch') {
        return {
            ...eventBase(normalizedItem, lifecycleStatus, 'Web search'),
            content: normalizedItem.query,
            output: boundedAgentResult(normalizedContent(normalizedItem.action) ?? ''),
        };
    }
    if (type === 'imageView') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Image view'), content: normalizedItem.path };
    }
    if (type === 'plan') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Plan'), content: normalizedItem.text };
    }
    if (type === 'contextCompaction') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Context compacted') };
    }
    if (type === 'enteredReviewMode' || type === 'exitedReviewMode') {
        const label = type === 'enteredReviewMode' ? 'Entered review mode' : 'Exited review mode';

        return { ...eventBase(normalizedItem, lifecycleStatus, label), content: normalizedItem.review };
    }

    return null;
}

function diagnosticEvent(method, itemType, itemId, sequence) {
    const providerItemId = typeof itemId === 'string' && itemId.length > 0 ? itemId : 'unknown';
    const normalizedType = typeof itemType === 'string' && itemType.length > 0 ? itemType : 'unknown';

    return {
        content: `${method}: ${normalizedType} (${providerItemId})`,
        label: 'Codex protocol diagnostic',
        providerItemId: `diagnostic:${providerItemId}:${sequence}`,
        status: 'completed',
        type: 'diagnostic',
    };
}

function systemEvent(method, params) {
    const turnId = typeof params.turnId === 'string' ? params.turnId : 'unknown-turn';
    const providerItemId = `system:${turnId}:${method}`;
    if (method === 'model/rerouted') {
        return {
            content: `${params.fromModel} to ${params.toModel}: ${optionalContent(params.reason)}`,
            label: 'Model rerouted',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }
    if (method === 'model/safetyBuffering/updated') {
        return {
            content: optionalContent({ reasons: params.reasons, useCases: params.useCases }),
            label: 'Safety buffering',
            providerItemId,
            status: params.showBufferingUi ? 'inProgress' : 'completed',
            type: 'system',
        };
    }
    if (method === 'model/verification') {
        return {
            content: optionalContent(params.verifications),
            label: 'Model verification',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }

    return null;
}

module.exports = {
    countUnifiedDiffLines,
    diagnosticEvent,
    normalizeCodexEvent,
    systemEvent,
};

const { normalizeChangedPaths, normalizedContent } = require('./agent_event_utils');

const CODEX_FILE_ITEM_KEYS = new Set(['file', 'filechange', 'patch']);
const CODEX_SILENT_ITEM_KEYS = new Set(['agentmessage', 'usermessage', 'reasoning', 'error', 'file', 'filechange', 'patch']);

/**
 * `codex exec` and the codex app-server are different wire protocols and keep separate handlers,
 * but they describe the same item vocabulary in different casings (`file_change` / `fileChange`).
 * Only that shared vocabulary lives here; parsing stays with each protocol.
 */
function codexItemKey(item) {
    return typeof item?.type === 'string' ? item.type.replace(/[^a-z]/giu, '').toLowerCase() : '';
}

function isCodexFileItem(item) {
    return CODEX_FILE_ITEM_KEYS.has(codexItemKey(item));
}

function codexChangedPaths(item, rootPath) {
    if (!isCodexFileItem(item)) return [];
    const filePaths = typeof item.path === 'string' ? [item.path] : [];
    if (Array.isArray(item.changes)) filePaths.push(...item.changes.map((change) => change?.path));

    return normalizeChangedPaths(rootPath, filePaths);
}

/** Assistant messages, user echoes and reasoning reach the conversation elsewhere; skip them here. */
function codexTranscriptContent(item) {
    if (!item || CODEX_SILENT_ITEM_KEYS.has(codexItemKey(item))) return null;

    return normalizedContent(
        item.aggregated_output
        ?? item.aggregatedOutput
        ?? item.output
        ?? item.result
        ?? item.changes
        ?? item.command
        ?? item.path
        ?? item.name,
    );
}

function codexTranscriptEvents(item) {
    const content = codexTranscriptContent(item);

    return content ? [{ content, toolType: `tool.${item.type}` }] : [];
}

module.exports = { codexChangedPaths, codexTranscriptEvents };

const path = require('node:path');
const { normalizePath } = require('../../../../shared/path_utils.mjs');
const { logAgentEvent } = require('./agent_file_logger');

/**
 * Turn a provider-reported file path into a repo-relative POSIX pathspec, or null when the path
 * escapes the project root. Changed paths end up as `git add` arguments, so they must be relative,
 * slash-normalized (otherwise the same file arrives twice and dedupe fails) and root-confined
 * (otherwise a file the agent touched outside the repo would be pulled into a card commit).
 */
function normalizeChangedPath(rootPath, filePath) {
    if (typeof filePath !== 'string' || filePath.length === 0) return null;
    const resolvedRoot = path.resolve(rootPath);
    const resolvedPath = path.resolve(resolvedRoot, filePath);
    const relativePath = path.relative(resolvedRoot, resolvedPath);
    if (relativePath.length === 0 || relativePath === '..' || relativePath.startsWith(`..${path.sep}`) || path.isAbsolute(relativePath)) return null;

    return normalizePath(relativePath);
}

function normalizeChangedPaths(rootPath, filePaths) {
    return [...new Set(filePaths
        .map((filePath) => normalizeChangedPath(rootPath, filePath))
        .filter((filePath) => filePath !== null))];
}

/** Render a transcript payload as text; objects are serialized, empty values become null. */
function normalizedContent(value) {
    if (value === undefined || value === null) return null;
    const content = typeof value === 'string' ? value : JSON.stringify(value);

    return content.length > 0 ? content : null;
}

/** Split a stdout stream into complete JSON lines, holding the trailing partial line back. */
class JsonLineBuffer {
    constructor(label, onLine) {
        this.buffer = '';
        this.label = label;
        this.onLine = onLine;
    }

    push(chunk) {
        this.buffer += chunk.toString();
        const lines = this.buffer.split(/\r?\n/u);
        this.buffer = lines.pop() ?? '';
        for (const line of lines) this.emit(line);
    }

    finish() {
        if (this.buffer.length > 0) this.emit(this.buffer);
        this.buffer = '';
    }

    emit(line) {
        if (line.trim().length === 0) return;

        logAgentEvent('[agent:raw]', this.label, line);
        this.onLine(line);
    }
}

module.exports = { JsonLineBuffer, normalizeChangedPath, normalizeChangedPaths, normalizedContent };

