            ?.find(({ agent }) => agent === resolvedAgent.agent) ?? null;
        const hasPromptOverride = Object.hasOwn(input.runInput, 'prompt');
        const basePrompt = hasPromptOverride
            ? input.action.output?.kind === 'diagram' && !input.runInput.diagramPath
