    readonly getSnapshot = () => this.snapshot

    readonly subscribe = (listener: () => void) => {
        this.addEventListener(CHANGED_EVENT, listener)

        return () => this.removeEventListener(CHANGED_EVENT, listener)
    }

    start() {
        if (this.unsubscribers.length > 0) return

        this.unsubscribers = [
            actionRunRegistry.subscribeActionRun(this.action.id, this.context, this.handleRunCollectionChange),
            actionRunRegistry.subscribeContextEvents(this.context, this.handleRunEvent),
            this.bindingStore.subscribe(this.recalculate),
            this.conversationStore.subscribe(this.recalculate),
            this.historyStore.subscribe(this.recalculate),
            this.scopeStore.subscribe(this.recalculate),
        ]
        this.recalculate()
        void this.historyStore.load()
    }

    stop() {
        for (const unsubscribe of this.unsubscribers) unsubscribe()
        this.unsubscribers = []
    }

    readonly toggleScope = () => {
        this.scopeStore.toggle(this.snapshot?.conversationAvailable ?? false)
    }

    private readonly handleRunEvent = (event: ActionRunEvent) => {
        if (event.rootActionId !== this.action.id || event.type !== 'update') return
        if (event.update.kind === 'agentUsage' || event.update.kind === 'agentStarted' || event.update.kind === 'agentClosed') {
            this.recalculate()
            return
        }
        if (
            event.update.kind === 'agentEvent'
            && event.update.event.type === 'fileChange'
            && event.update.event.status === 'completed'
        ) this.recalculate()
    }

    private readonly handleRunCollectionChange = () => {
        const runStores = actionRunRegistry.getActionRunStores(this.action.id, this.context)
        const membershipChanged = runStores.length !== this.runStores.length
            || runStores.some((store, index) => store !== this.runStores[index])
        if (!membershipChanged) return

        this.runStores = runStores
        this.recalculate()
    }

    private readonly recalculate = () => {
        const cardInternalId = this.context.cardInternalId
        if (this.context.kind !== 'card' || !this.context.file || !cardInternalId || this.action.type !== 'agent') {
            this.publish(null)
            return
        }

        const boundRunId = this.bindingStore.getSnapshot()
        const liveConversation = boundRunId
            ? actionRunRegistry.getRunStore(boundRunId)?.getSnapshot().conversation ?? null
            : null
        const liveConversations = actionRunRegistry.getActionRunStores(this.action.id, this.context)
            .map(({ getSnapshot }) => getSnapshot().conversation)
            .filter((conversation) => !!conversation)
        const conversationSnapshot = this.conversationStore.getSnapshot()
        const displayedConversation = resolveDisplayedConversation(
            liveConversation,
            conversationSnapshot.selectedConversation,
        )
        const conversations = this.conversationStore.conversationOptions(liveConversations)
        const usage = scopedActionUsage(
            conversations,
            liveConversation,
            displayedConversation,
            this.historyStore.getSnapshot().entries,
            this.action.id,
            cardInternalId,
        )
        const conversationAvailable = !!displayedConversation
        if (!conversationAvailable) this.scopeStore.useActionCardScope()
        const requestedScope = this.scopeStore.getSnapshot()
        const activeScope = requestedScope === 'conversation' && usage.conversation ? 'conversation' : 'actionCard'
        this.publish({ ...usage, activeScope, conversationAvailable })
    }

    private publish(snapshot: ActionUsageValuesSnapshot | null) {
        if (snapshotsMatch(this.snapshot, snapshot)) return

        this.snapshot = snapshot
        this.dispatchEvent(new Event(CHANGED_EVENT))
    }
}

import type { AgentConversation, AgentTokenUsage } from '../../../../data/data_types'
import type { ActionRunHistoryEntry, CommitReference } from '../../../../data/electron_action_bridge'
import {
    conversationFileChangeUsage,
    sumAgentTokenUsage,
    type AgentFileChangeUsage,
} from '../../../../services/agents/agent_usage'

export interface LineUsage {
    commits: CommitReference[]
    deletions: number
    filesChanged: number
    insertions: number
}

export interface ActionUsageValues {
    changes: AgentFileChangeUsage | null
    lines: LineUsage
    tokens: AgentTokenUsage
}

export interface ScopedActionUsage {
    actionCard: ActionUsageValues
    conversation: ActionUsageValues | null
}

function conversationsForActionCard(
    conversations: AgentConversation[],
    liveConversation: AgentConversation | null,
    actionId: string,
    cardInternalId: string,
) {
    const conversationsById = new Map<string, AgentConversation>()
    for (const conversation of conversations) {
        if (conversation.actionId !== actionId || conversation.cardInternalId !== cardInternalId) continue

        conversationsById.set(conversation.id, conversation)
    }
    if (liveConversation?.actionId === actionId && liveConversation.cardInternalId === cardInternalId) {
        conversationsById.set(liveConversation.id, liveConversation)
    }

    return [...conversationsById.values()]
}

/** Sums reported patches; `null` when no conversation in scope reported any file change. */
function fileChangeUsage(conversations: AgentConversation[]) {
    return conversations.reduce<AgentFileChangeUsage | null>((total, conversation) => {
        const usage = conversationFileChangeUsage(conversation)
        if (!usage) return total
        if (!total) return { deletions: usage.deletions, insertions: usage.insertions }

        return { deletions: total.deletions + usage.deletions, insertions: total.insertions + usage.insertions }
    }, null)
}

function lineUsage(history: ActionRunHistoryEntry[]): LineUsage {
    const commits = history.flatMap((entry) => entry.commits ?? [])

    return commits.reduce((totals, commit) => ({
        commits: totals.commits,
        deletions: totals.deletions + commit.deletions,
        filesChanged: totals.filesChanged + commit.filesChanged,
        insertions: totals.insertions + commit.insertions,
    }), { commits, deletions: 0, filesChanged: 0, insertions: 0 })
}

function usageValues(conversations: AgentConversation[], history: ActionRunHistoryEntry[]): ActionUsageValues {
    return {
        changes: fileChangeUsage(conversations),
        lines: lineUsage(history),
        tokens: sumAgentTokenUsage(conversations.map(({ usage }) => usage)),
    }
}

/** Aggregates every usage metric for conversation and action/card scopes. */
export function scopedActionUsage(
    conversations: AgentConversation[],
    liveConversation: AgentConversation | null,
    displayedConversation: AgentConversation | null,
    history: ActionRunHistoryEntry[],
    actionId: string,
    cardInternalId: string,
): ScopedActionUsage {
    const actionCardConversations = conversationsForActionCard(
        conversations,
        liveConversation,
        actionId,
        cardInternalId,
    )
    const actionCard = usageValues(actionCardConversations, history)
    if (!displayedConversation) return { actionCard, conversation: null }

    const conversationHistory = history.filter((entry) => (
        entry.type === 'agent' && entry.rootConversationId === displayedConversation.id
    ))

    return {
        actionCard,
        conversation: usageValues([displayedConversation], conversationHistory),
    }
}

import { Stack } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { useBoundRunId, useRunSelector } from '../../../hooks/use_action_runs'
import { ActionAgentApprovals } from '../../agent/action_agent_approvals'
import { ActionPromptOwner } from '../../agent/action_prompt_owner'
import { ActionConversationChat } from '../../conversation/action_conversation_chat'
import { ActionLogErrorOwner } from '../../conversation/errors/action_log_error_owner'
import type { ActionPopupRuntime } from './action_popup_types'

interface ActionAgentInteractionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    popupEntryId?: string
    popupVisible?: boolean
    runtime: ActionPopupRuntime
}

/** Agent interaction surface, including agent children started by command actions. */
export function ActionAgentInteraction(props: ActionAgentInteractionProps) {
    const { action, assignmentContext, popupEntryId, popupVisible, runtime } = props
    const {
        bindingStore, conversationSearchService, conversationStore, historyStore, inputStore, resultStore,
        runValidationError, scheduleStore, settingsStore, usageValuesService,
    } = runtime
    const boundRunId = useBoundRunId(bindingStore)
    const activeActionType = useRunSelector(boundRunId, (run) => run?.activeActionType ?? null)
    const visible = action.type === 'agent' || activeActionType === 'agent'
    const displayedUsageValuesService = action.type === 'agent'
        && assignmentContext.kind === 'card'
        && !!assignmentContext.file
        && !!assignmentContext.cardInternalId
        ? usageValuesService
        : undefined

    if (!visible) return null

    return (
        <Stack sx={{ display: 'contents' }}>
            <Stack spacing={1} sx={{ flex: 1, minHeight: 0 }}>
                <ActionLogErrorOwner bindingStore={bindingStore} resultStore={resultStore} />
                <ActionConversationChat
                    actionId={action.id}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    popupVisible={popupVisible}
                    searchService={conversationSearchService}
                    store={conversationStore}
                    usageValuesService={displayedUsageValuesService}
                />
                <ActionPromptOwner
                    action={action}
                    bindingStore={bindingStore}
                    context={assignmentContext}
                    conversationStore={conversationStore}
                    historyStore={historyStore}
                    inputStore={inputStore}
                    questionsEnabled
                    settingsStore={settingsStore}
                    resultStore={resultStore}
                    runValidationError={runValidationError}
                    scheduleStore={scheduleStore}
                />
                <ActionAgentApprovals bindingStore={bindingStore} />
            </Stack>
        </Stack>
    )
}

